// Arduino Sketch

#include <DHT.h>
#include <DHT11_Sensor.h>

#define DHTPIN 4
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

void setup()
{
  Serial.begin(115200);
  delay(1500);

  Serial.println();
  Serial.println("=== DHT11 HARDWARE TEST ===");

  dht.begin();
}

void loop()
{
  delay(2000);

  float h = dht.readHumidity();
  float t = dht.readTemperature();

  if (isnan(h) || isnan(t))
  {
    Serial.println("READ FAILED");
    Serial.println("Check DATA, VCC, GND and pull-up.");
  }
  else
  {
    Serial.print("Temperature: ");
    Serial.print(t);
    Serial.print(" C, Humidity: ");
    Serial.print(h);
    Serial.println(" %");
  }
}
